-- ---------- TABLES ----------
CREATE TABLE WARD_INFRASTRUCTURE (
  ward_id            VARCHAR2(20)  PRIMARY KEY,
  city_name          VARCHAR2(50)  NOT NULL,
  zone_name          VARCHAR2(20)  NOT NULL,
  ward_name          VARCHAR2(100) NOT NULL,
  number_of_poles    NUMBER(8)     NOT NULL,
  led_bulbs          NUMBER(8)     NOT NULL,
  conventional_poles NUMBER(8)     NOT NULL,
  road_length_km     NUMBER(8,2)   NOT NULL,
  lights_per_km      NUMBER(6,2),
  total_streets      NUMBER(8),
  adequate_streets   NUMBER(8),
  CONSTRAINT chk_ward_counts CHECK (number_of_poles >= 0 AND led_bulbs >= 0
    AND conventional_poles >= 0 AND road_length_km > 0)
);

CREATE TABLE LOCATION (
  location_id VARCHAR2(20) PRIMARY KEY,
  ward_no     VARCHAR2(20),
  area_name   VARCHAR2(100),
  street_name VARCHAR2(100),
  latitude    NUMBER(9,6),
  longitude   NUMBER(9,6),
  ward_id     VARCHAR2(20) REFERENCES WARD_INFRASTRUCTURE(ward_id),
  CONSTRAINT chk_lat CHECK (latitude BETWEEN -90 AND 90),
  CONSTRAINT chk_lon CHECK (longitude BETWEEN -180 AND 180)
);

CREATE TABLE STREET_LIGHT (
  light_id          VARCHAR2(20) PRIMARY KEY,
  location_id       VARCHAR2(20) NOT NULL REFERENCES LOCATION(location_id),
  installation_date DATE,
  light_type        VARCHAR2(50),
  power_rating      NUMBER(6,2),
  current_status    VARCHAR2(30) DEFAULT 'ACTIVE' NOT NULL,
  CONSTRAINT chk_power CHECK (power_rating > 0),
  CONSTRAINT chk_light_status CHECK (current_status IN
    ('ACTIVE','FAULTY','MAINTENANCE','REPLACEMENT REVIEW','DECOMMISSIONED'))
);

CREATE TABLE FAILURE (
  failure_id          VARCHAR2(20) PRIMARY KEY,
  light_id            VARCHAR2(20) NOT NULL REFERENCES STREET_LIGHT(light_id),
  failure_date        DATE NOT NULL,
  failure_type        VARCHAR2(30) NOT NULL,
  failure_description VARCHAR2(255),
  resolved_date       DATE,
  CONSTRAINT chk_failure_type CHECK (failure_type IN
    ('Bulb Burnout','Power Surge','Wiring Fault','Driver Failure','Pole Damage','Other')),
  CONSTRAINT chk_resolved CHECK (resolved_date IS NULL OR resolved_date >= failure_date)
);

CREATE TABLE INSPECTION (
  inspection_id   VARCHAR2(20) PRIMARY KEY,
  light_id        VARCHAR2(20) NOT NULL REFERENCES STREET_LIGHT(light_id),
  inspection_date DATE NOT NULL,
  condition_status VARCHAR2(20) NOT NULL,
  remarks         VARCHAR2(255),
  CONSTRAINT chk_condition CHECK (condition_status IN ('GOOD','FAIR','POOR','CRITICAL'))
);

CREATE TABLE CONTRACTOR (
  contractor_id   VARCHAR2(20) PRIMARY KEY,
  contractor_name VARCHAR2(100) NOT NULL,
  company_name    VARCHAR2(100),
  contact_number  VARCHAR2(30)
);

CREATE TABLE MAINTENANCE (
  maintenance_id   VARCHAR2(20) PRIMARY KEY,
  light_id         VARCHAR2(20) NOT NULL REFERENCES STREET_LIGHT(light_id),
  contractor_id    VARCHAR2(20) NOT NULL REFERENCES CONTRACTOR(contractor_id),
  maintenance_date DATE,
  maintenance_type VARCHAR2(50),
  description      VARCHAR2(255),
  status           VARCHAR2(20) DEFAULT 'PENDING' NOT NULL,
  CONSTRAINT chk_maint_status CHECK (status IN ('PENDING','IN PROGRESS','COMPLETED','VERIFIED'))
);

CREATE TABLE EXPENDITURE (
  expenditure_id   VARCHAR2(20) PRIMARY KEY,
  maintenance_id   VARCHAR2(20) NOT NULL REFERENCES MAINTENANCE(maintenance_id),
  amount           NUMBER(10,2) NOT NULL,
  expenditure_date DATE,
  payment_status   VARCHAR2(20) DEFAULT 'PAID' NOT NULL,
  CONSTRAINT chk_amount CHECK (amount >= 0),
  CONSTRAINT chk_payment CHECK (payment_status IN ('PAID','PENDING','REJECTED'))
);

CREATE TABLE LIGHT_AUDIT_LOG (
  audit_id         NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  light_id         VARCHAR2(20),
  old_status       VARCHAR2(30),
  new_status       VARCHAR2(30),
  changed_by       VARCHAR2(50) DEFAULT USER,
  change_timestamp TIMESTAMP DEFAULT SYSTIMESTAMP
);

CREATE SEQUENCE SEQ_FAILURE_ID START WITH 64 INCREMENT BY 1 NOCACHE;

-- ---------- INDEXES ----------
CREATE INDEX idx_light_location ON STREET_LIGHT(location_id);
CREATE INDEX idx_light_status   ON STREET_LIGHT(current_status);
CREATE INDEX idx_failure_light  ON FAILURE(light_id);
CREATE INDEX idx_failure_date   ON FAILURE(failure_date);
CREATE INDEX idx_insp_light     ON INSPECTION(light_id);
CREATE INDEX idx_maint_light    ON MAINTENANCE(light_id);
CREATE INDEX idx_maint_contr    ON MAINTENANCE(contractor_id);
CREATE INDEX idx_exp_maint      ON EXPENDITURE(maintenance_id);
CREATE INDEX idx_audit_light    ON LIGHT_AUDIT_LOG(light_id);

-- ---------- VIEWS ----------
CREATE OR REPLACE VIEW V_CONTRACTOR_PERFORMANCE AS
SELECT c.contractor_id, c.contractor_name, c.company_name,
       COUNT(DISTINCT m.maintenance_id) AS total_jobs_assigned,
       NVL(SUM(e.amount), 0)            AS total_amount_billed
FROM CONTRACTOR c
LEFT JOIN MAINTENANCE m ON m.contractor_id = c.contractor_id
LEFT JOIN EXPENDITURE e ON e.maintenance_id = m.maintenance_id
GROUP BY c.contractor_id, c.contractor_name, c.company_name;

CREATE OR REPLACE VIEW V_WARD_LED_COVERAGE AS
SELECT ward_id, zone_name, ward_name, number_of_poles, conventional_poles,
       ROUND((number_of_poles - conventional_poles) / number_of_poles * 100, 2) AS led_pole_coverage_pct,
       ROUND(led_bulbs / number_of_poles, 2)       AS bulbs_per_pole,
       ROUND(number_of_poles / road_length_km, 1)  AS poles_per_km
FROM WARD_INFRASTRUCTURE;

-- ---------- PL/SQL ----------
CREATE OR REPLACE FUNCTION GET_TOTAL_REPAIR_COST(p_light_id IN VARCHAR2) RETURN NUMBER IS
  v_total NUMBER;
BEGIN
  SELECT NVL(SUM(e.amount), 0) INTO v_total
  FROM EXPENDITURE e JOIN MAINTENANCE m ON m.maintenance_id = e.maintenance_id
  WHERE m.light_id = p_light_id;
  RETURN v_total;
END GET_TOTAL_REPAIR_COST;
/

CREATE OR REPLACE PROCEDURE EVALUATE_REPLACEMENT_REVIEW(
  p_min_failures  IN  NUMBER DEFAULT 3,
  p_min_cost      IN  NUMBER DEFAULT 5000,
  p_updated_count OUT NUMBER) IS
BEGIN
  p_updated_count := 0;
  FOR r IN (
    SELECT s.light_id, s.current_status,
           COUNT(f.failure_id) AS fail_cnt,
           GET_TOTAL_REPAIR_COST(s.light_id) AS total_cost
    FROM STREET_LIGHT s
    LEFT JOIN FAILURE f ON f.light_id = s.light_id
    WHERE s.current_status <> 'DECOMMISSIONED'
    GROUP BY s.light_id, s.current_status
  ) LOOP
    IF r.fail_cnt >= p_min_failures AND r.total_cost >= p_min_cost
       AND r.current_status <> 'REPLACEMENT REVIEW' THEN
      UPDATE STREET_LIGHT SET current_status = 'REPLACEMENT REVIEW'
      WHERE light_id = r.light_id;
      p_updated_count := p_updated_count + 1;
    END IF;
  END LOOP;
  COMMIT;
END EVALUATE_REPLACEMENT_REVIEW;
/

CREATE OR REPLACE TRIGGER TRG_AUTO_LOG_FAILURE_STATUS
AFTER INSERT ON FAILURE
FOR EACH ROW
BEGIN
  UPDATE STREET_LIGHT SET current_status = 'FAULTY'
  WHERE light_id = :NEW.light_id AND current_status <> 'DECOMMISSIONED';
END;
/

CREATE OR REPLACE TRIGGER trg_light_status_audit
AFTER UPDATE OF current_status ON STREET_LIGHT
FOR EACH ROW
WHEN (OLD.current_status <> NEW.current_status)
BEGIN
  VALUES (:OLD.light_id, :OLD.current_status, :NEW.current_status, USER, SYSTIMESTAMP);
END;
/

-- ---------- SEED: WARD_INFRASTRUCTURE (dataset.csv, real data; NA stored as NULL) ----------

-- ---------- SEED: SAMPLE operational records ----------

-- Failures: the trigger sets lights to FAULTY and writes audit rows

-- Status clean-up, then the review engine
UPDATE STREET_LIGHT SET current_status = 'ACTIVE'
 WHERE current_status = 'FAULTY'
   AND light_id NOT IN (SELECT light_id FROM FAILURE WHERE resolved_date IS NULL);
UPDATE STREET_LIGHT SET current_status = 'MAINTENANCE'
 WHERE light_id IN (SELECT light_id FROM MAINTENANCE WHERE status = 'IN PROGRESS');
COMMIT;

DECLARE
  v_flagged NUMBER;
BEGIN
  EVALUATE_REPLACEMENT_REVIEW(3, 5000, v_flagged);
  DBMS_OUTPUT.PUT_LINE('Lights moved to REPLACEMENT REVIEW: ' || v_flagged);
END;
/

COMMIT;
